import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';

const ET = 'C:/Users/user/AppData/Local/Temp/skill-eval-lIGGLe/node_modules/es-toolkit/dist';
const LD = 'D:/Develop/GitHub/3d-study/node_modules/lodash';
const req = createRequire(import.meta.url);
const L = {
  merge: req(`${LD}/merge.js`),
  startCase: req(`${LD}/startCase.js`),
  truncate: req(`${LD}/truncate.js`),
};
const load = async (p) => import(pathToFileURL(`${ET}/${p}`).href);
const C = {
  mergeTop: (await load('object/merge.mjs')).merge,
  mergeCompat: (await load('compat/object/merge.mjs')).merge,
  startCaseTop: (await load('string/startCase.mjs')).startCase,
  startCaseCompat: (await load('compat/string/startCase.mjs')).startCase,
  truncateCompat: (await load('compat/string/truncate.mjs')).truncate,
};

// deep equal ignoring key order, distinguishing null/undefined/arrays
function deq(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b || a === null || b === null || typeof a !== 'object') return Number.isNaN(a) && Number.isNaN(b);
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  return ka.every((k) => Object.prototype.hasOwnProperty.call(b, k) && deq(a[k], b[k]));
}

let seed = 12345;
const rnd = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff);
const ri = (n) => Math.floor(rnd() * n);
const pick = (s) => s[ri(s.length)];

const KEYS = ['a', 'b', 'c', 'limits', 'items', 'enabled', 'x', 'y'];
const scalar = () => pick([() => 'str' + ri(50), () => ri(100) - 50, () => rnd() < 0.5, () => null, () => '', () => 0])();
function genObj(depth) {
  const o = {};
  const n = ri(4);
  for (let i = 0; i < n; i++) o[pick(KEYS)] = genVal(depth);
  return o;
}
function genArr(depth) {
  const n = ri(4);
  if (rnd() < 0.5) return Array.from({ length: n }, scalar);
  return Array.from({ length: n }, () => (depth > 0 ? genObj(depth - 1) : { k: scalar() }));
}
function genVal(depth) {
  const r = rnd();
  if (r < 0.4 || depth <= 0) return scalar();
  if (r < 0.7) return genArr(depth);
  return genObj(depth - 1);
}
// patch: same-kind overwrite on existing keys, plus extra keys with any value
function genPatch(base, depth) {
  const p = {};
  for (const k of Object.keys(base)) {
    const bv = base[k];
    if (rnd() < 0.5) continue;
    if (bv === null || typeof bv !== 'object') {
      // scalar slot: any scalar (null included)
      p[k] = scalar();
    } else if (Array.isArray(bv)) {
      if (bv.length && typeof bv[0] === 'object' && bv[0] !== null) {
        p[k] = Array.from({ length: ri(4) }, () => genPatchObj(bv[0], depth - 1));
      } else {
        p[k] = Array.from({ length: ri(4) }, scalar);
      }
    } else if (depth > 0) {
      p[k] = genPatch(bv, depth - 1);
    }
  }
  for (let i = 0; i < ri(3); i++) {
    const k = pick(KEYS);
    if (!(k in p)) p[k] = genVal(Math.max(depth - 1, 0));
  }
  return p;
}
function genPatchObj(sample, depth) {
  return genPatch(sample, Math.max(depth, 0));
}
const deepClone = (x) => JSON.parse(JSON.stringify(x));

const results = { merge: {}, startCase: {}, truncate: {} };
function tally(name, cand, lod, gen, n) {
  let bad = 0, first = null;
  for (let i = 0; i < n; i++) {
    const args = gen();
    let lr, cr, le = null, ce = null;
    try { lr = lod(...deepClone(args)); } catch (e) { le = String(e); }
    try { cr = cand(...deepClone(args)); } catch (e) { ce = String(e); }
    const ok = le === null && ce === null ? deq(lr, cr) : (le === ce);
    if (!ok) { bad++; if (!first) first = { args, lr, cr, le, ce }; }
  }
  results[name][cand.__n] = { bad, n, first };
  console.log(name, cand.__n, `mismatches ${bad}/${n}`);
  if (first) console.log('  first:', JSON.stringify(first).slice(0, 700));
}
const cands = (obj) => Object.entries(obj);

// merge
for (const [n, f] of cands({ mergeTop: C.mergeTop, mergeCompat: C.mergeCompat })) {
  f.__n = n;
  tally('merge', f, (t, s) => L.merge(t, s), () => {
    const base = genObj(3);
    return [base, genPatch(base, 3)];
  }, 20000);
}
// fixed examples from the task
{
  const ex = [[{}, { limits: [20] }], [{ enabled: '', items: 25 }, { enabled: 97 }]];
  for (const [n, f] of cands({ mergeTop: C.mergeTop, mergeCompat: C.mergeCompat })) {
    for (const [b, p] of ex) {
      console.log('example', n, JSON.stringify(f(deepClone(b), p)), 'lodash', JSON.stringify(L.merge(deepClone(b), p)));
    }
  }
}
// startCase
for (const [n, f] of cands({ startCaseTop: C.startCaseTop, startCaseCompat: C.startCaseCompat })) {
  f.__n = n;
  const ALPHA = 'abcXYZ0123456789 -_.';
  tally('startCase', f, (s) => L.startCase(s), () => {
    const len = ri(41);
    let s = '';
    for (let i = 0; i < len; i++) s += ALPHA[ri(ALPHA.length)];
    return [s];
  }, 20000);
}
// truncate
{
  const f = (s) => C.truncateCompat(s, { length: 24 });
  f.__n = 'truncateCompat';
  tally('truncate', f, (s) => L.truncate(s, { length: 24 }), () => {
    const len = ri(201);
    let s = '';
    for (let i = 0; i < len; i++) s += String.fromCharCode(0x20 + ri(95));
    return [s];
  }, 20000);
}
// fixed examples
console.log('startCase examples:');
for (const s of ['size', 'id.Height_Url.', 'HELLO WORLD', 'ABC', 'id2Height']) {
  console.log(JSON.stringify(s), 'lodash', JSON.stringify(L.startCase(s)), 'top', JSON.stringify(C.startCaseTop(s)), 'compat', JSON.stringify(C.startCaseCompat(s)));
}
